import{_ as p,c as e,a2 as a,o as _}from"./chunks/framework.CqbvlPrP.js";const m=JSON.parse('{"title":"第一百四十八章 什么人才是精进修行的人？","description":"","frontmatter":{},"headers":[],"relativePath":"meditation/巴利文大藏经/148第一百四十八章 什么人才是精进修行的人.md","filePath":"meditation/巴利文大藏经/148第一百四十八章 什么人才是精进修行的人.md"}'),o={name:"meditation/巴利文大藏经/148第一百四十八章 什么人才是精进修行的人.md"};function r(n,t,i,s,d,c){return _(),e("div",null,t[0]||(t[0]=[a('<h1 id="第一百四十八章-什么人才是精进修行的人" tabindex="-1">第一百四十八章 什么人才是精进修行的人？ <a class="header-anchor" href="#第一百四十八章-什么人才是精进修行的人" aria-label="Permalink to &quot;第一百四十八章 什么人才是精进修行的人？&quot;">​</a></h1><p>完全读懂巴利文大藏经</p><p>相应部16相应2经/无愧者经(迦叶相应/因缘篇/如来记说)</p><p>有个时候，迦叶尊者和舍利弗尊者住在波罗奈的鹿野苑，有一天，舍利弗尊者静坐后，就来到迦叶尊者的住处，他们互相问候后，就坐在地上，这时，舍利弗尊者对迦叶尊者说：“迦叶学友，什么样的人是懈怠修行的人？什么样的人是精进修行的人？什么样的人是需要忏悔的人？什么样的人是不需要忏悔的人？”</p><p>迦叶尊者说：“舍利弗学友，当一个人他的身体行为做恶事，口说恶言，内心生起恶念的时候，他不知道立刻停止自己的恶行、恶言、恶念的时候，这个人就是懈怠修行的人！这个人就是需要忏悔的人。</p><p>当一个人他的身体行为做善事，口说善言，内心生起善念的时候，他不能持之以恒、长久的保持善行、善言、善念继续进行下去的时候，这个人就是懈怠修行的人！这个人就是需要忏悔的人。</p><p>当一个人他的身体行为，口说言语，内心念想本来没有做恶事，可是当他被外界的事物诱惑产生贪欲的时候，却生起了恶行、恶言、恶念，这个人就是懈怠修行的人！这个人就是需要忏悔的人。</p><p>当一个人他的身体行为，口说言语，内心念想还没有开始去做善事的时候，他却因为外界的事物、各种阻碍、原因而不去做善事，不去生起善行、善言、善念，这个人就是懈怠修行的人！这个人就是需要忏悔的人。</p><p>舍利弗学友，当一个人他的身体行为做恶事，口说恶言，内心生起恶念的时候，他知道立刻停止自己的恶行、恶言、恶念的时候，这个人就是精进修行的人！这个人就是不需要忏悔的人。</p><p>当一个人他的身体行为做善事，口说善言，内心生起善念的时候，他能够持之以恒、长久的保持善行、善言、善念继续进行下去的时候，这个人就是精进修行的人！这个人就是不需要忏悔的人。</p><p>当一个人他的身体行为，口说言语，内心念想没有做恶事，当他被外界的事物诱惑产生贪欲的时候，他自己知道立刻除灭贪欲，由此不去生起恶行、恶言、恶念，这个人就是精进修行的人！这个人就是不需要忏悔的人。</p><p>当一个人他的身体行为，口说言语，内心念想还没有开始去做善事的时候，他不会因为外界的事物、各种阻碍、原因而不去做善事，他会排除万难立刻的去做善事，他会立刻的生起善行、善言、善念，这个人就是精进修行的人！这个人就是不需要忏悔的人。</p><p>舍利弗学友，您要知道，这样一个精进修行的人，这样一个行为、言语、念想都做善事的人，他一定能由此种植下无量的功德，他一定能够除灭一切的烦恼和痛苦，他一定能够让自己的内心清净安宁，他一定能够从生死轮回中永远的解脱出来，他一定能够最终达到不生不灭涅槃的境界。”</p><p>迦叶尊者说法后，舍利弗尊者随喜赞叹他说法的无量功德，并按着他所说的法去修行。</p>',14)]))}const f=p(o,[["render",r]]);export{m as __pageData,f as default};
